// Parses the specs generated by figma-template/build-template.js (exported from Figma, compact form).
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { DEFAULT_CONFIG as cfg } from "../src/config.js";
import { lintScreen } from "../src/spec/lint.js";
import { findScreenDocs, parseScreen } from "../src/spec/parse.js";
import { draftTicket } from "../src/spec/ticket.js";
import type { FigmaNode } from "../src/spec/types.js";

type Compact = [string, string, string, (Compact[] | string)?];
const TYPES: Record<string, string> = { F: "FRAME", T: "TEXT", I: "INSTANCE" };
function expand([id, name, t, rest]: Compact): FigmaNode {
  const type = TYPES[t];
  const n: FigmaNode = { id: `1:${id}`, name, type };
  if (type === "TEXT") n.characters = name;
  if (type === "INSTANCE") n.componentProperties = { v: { type: "VARIANT", value: String(rest ?? "") } };
  else if (Array.isArray(rest)) n.children = rest.map(expand);
  return n;
}
const load = (lang: string) =>
  expand(JSON.parse(readFileSync(new URL(`./fixtures/compact-${lang}.json`, import.meta.url), "utf8")));

for (const [lang, expectTitle, expectStatus, fn] of [
  ["ko", "장바구니 목록", "검토중", "기능"],
  ["en", "Cart list", "In review", "Function"],
] as const) {
  describe(`generated template (${lang})`, () => {
    const docs = findScreenDocs(load(lang), cfg);
    const s = parseScreen(docs[0], cfg, "FILE");

    it("is detected and parsed", () => {
      expect(docs).toHaveLength(1);
      expect(s).toMatchObject({ screenId: "C-02", title: expectTitle, version: "v1.2", status: expectStatus, isTemplate: false });
      expect(s.owners).toHaveLength(4);
      expect(s.overview.every((f) => f.filled)).toBe(true);
    });

    it("reads both elements", () => {
      expect(s.items.map((i) => i.no)).toEqual([1, 2]);
      expect(s.items[0].pm[0].label).toBe(fn);
      expect(s.items[0].pm.every((f) => f.filled)).toBe(true);
      expect(s.items[1].design.every((f) => !f.filled)).toBe(true);
    });

    it("reads feedback and change log", () => {
      expect(s.feedback.map((f) => f.jiraKey)).toEqual(["DEMO-128", "DEMO-131", "DEMO-119"]);
      expect(s.feedback[1].lastComment).toBeUndefined();
      expect(s.changeLog.map((r) => r.version)).toEqual(["v1.0", "v1.1", "v1.2"]);
    });

    it("lints: PM complete, design partial, versions consistent", () => {
      const r = lintScreen(s, cfg);
      expect(r.completeness.pm).toBe(100);
      expect(r.counts.error).toBe(0);
      expect(r.issues.some((i) => i.where === "changeLog")).toBe(false);
    });

    it("drafts a ticket in the spec's language", () => {
      const t = draftTicket(s, s.items[0], cfg);
      expect(t.labels).toContain("C-02");
      expect(t.acceptanceCriteria.length).toBeGreaterThan(5);
      expect(t.description).toContain(lang === "en" ? "## Acceptance criteria" : "## 완료 조건");
      expect(t.description).toContain("DEMO-128"); // open feedback on element 1
      expect(t.description).not.toContain("DEMO-119"); // closed
    });
  });
}
